questionvariables.text:
/* Use predefined coprime tuples to ensure clean integer intercepts */
tuples : [[2, 3, 6], [3, 2, 6], [3, 4, 12], [4, 3, 12], [2, 5, 10], [5, 2, 10], [1, 2, 4], [2, 1, 4], [1, 3, 6], [3, 1, 6]];
tup : rand(tuples);
A_mag : tup[1];
B_mag : tup[2];
C_mag : tup[3];

sign_A : rand([1, -1]);
sign_B : rand([1, -1]);
sign_C : rand([1, -1]);

A : A_mag * sign_A;
B : B_mag * sign_B;
C : C_mag * sign_C;

/* Target Intercepts */
ta1 : C / B;
ta2 : C / A;

/* Graph Line Targets */
ta3 : [0, ta1];
ta4 : [ta2, 0];

/* Region Marker Targets - dynamically determined to guarantee safe placement */
ta5_check : if (0 <= C) then true else false;
ta5 : if ta5_check then [0, 0] else [-8 * sign_A, -8 * sign_B];
ta5_wrong : [8 * sign_A, 8 * sign_B];

/* Text variables for the worked solution */
origin_statement : if ta5_check then "is <b>true</b>, so the origin \\((0,0)\\) belongs in the solution region" else "is <b>false</b>, so the origin \\((0,0)\\) is NOT in the solution region";

feedbackvariables.text:
/* Extract coordinates of the two blue points */
x1 : ans3[1];
y1 : ans3[2];
x2 : ans4[1];
y2 : ans4[2];

/* Extract coordinate of the green region marker */
rx : ans5[1];
ry : ans5[2];
